head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getColumnNodeSet]<br/>Body Column 정보를 사용하여 특정 Column 의 아이템으로 바인딩된 DataList 정보를 객체로 반환합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 아이템으로 바인딩된 DataList 정보를 조회할 Body Column 의 ID 를 설정할 수 있어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - 옵션용 DataList(dlt_grade) : value ref=gCode, label ref=gLabel
//  - select/checkcombobox/autoComplete Column 은 dlt_grade 를 itemset(nodeset) 으로 바인딩 -> 채워진 객체 반환
//  - text Column -> undefined / 정적 인라인 ItemSet select Column -> 빈 문자열 객체
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_grade !== 'undefined') {
        $p.data.remove("dlt_grade");
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Body Column ID - name(text) / memo(text, 숨김) / grade(select, dlt_grade nodeset itemset) / region(checkcombobox, dlt_grade nodeset itemset) / city(autoComplete, dlt_grade nodeset itemset) / type(select, 정적 인라인 item). dlt_grade 는 value ref=gCode, label ref=gLabel.\n[절차] columnInfo(ID) 선택 후 (getColumnNodeSet) 클릭. noexist 는 존재하지 않는 ID.\n[확인] nodeset itemset(grade/region/city)=채워진 객체(nodeset=data:dlt_grade, value=gCode, label=gLabel) / 정적 item(type)=빈 문자열 객체 / text(name)·없는ID(noexist)=undefined 가 반환영역에 출력됨."', '', 'label1');

    // 옵션용 DataList (코드/라벨) - value ref=gCode, label ref=gLabel
    let strGrade = '';
    strGrade += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_grade" baseNode="list" repeatNode="map">';
    strGrade += '<w2:columnInfo>';
    strGrade += '<w2:column id="gCode" name="gCode" dataType="text"></w2:column>';
    strGrade += '<w2:column id="gLabel" name="gLabel" dataType="text"></w2:column>';
    strGrade += '</w2:columnInfo>';
    strGrade += '<w2:data use="true"></w2:data>';
    strGrade += '</w2:dataList>';
    $p.data.create(strGrade);
    dlt_grade.setJSON([
        { "gCode": "A", "gLabel": "최우수" },
        { "gCode": "B", "gLabel": "우수" },
        { "gCode": "C", "gLabel": "보통" }
    ], false);

    // GridView 와 바인딩할 DataList 동적 생성 (각 Column 별 데이터)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '<w2:column id="grade" name="grade" dataType="text"></w2:column>';
    strDlt += '<w2:column id="region" name="region" dataType="text"></w2:column>';
    strDlt += '<w2:column id="city" name="city" dataType="text"></w2:column>';
    strDlt += '<w2:column id="type" name="type" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // checkcombobox(region) 다중값은 공백 구분 코드값
    let jsonData = [
        { "name": "노트북", "memo": "재고확인", "grade": "A", "region": "A B", "city": "A", "type": "1" },
        { "name": "모니터", "memo": "신규입고", "grade": "B", "region": "B C", "city": "B", "type": "2" },
        { "name": "키보드", "memo": "할인적용", "grade": "C", "region": "A C", "city": "C", "type": "1" },
        { "name": "마우스", "memo": "주문대기", "grade": "A", "region": "B", "city": "A", "type": "2" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // itemset(nodeset) 공통 조각 (select/checkcombobox/autoComplete 용) : label ref=gLabel, value ref=gCode
    let itemset = '<w2:choices><w2:itemset nodeset="data:dlt_grade"><w2:label ref="gLabel"></w2:label><w2:value ref="gCode"></w2:value></w2:itemset></w2:choices>';
    // 정적 인라인 ItemSet (DataList nodeset 아님) - 빈 문자열 객체 반환 검증용
    let staticItemset = '<w2:choices><w2:item><w2:label>일반</w2:label><w2:value>1</w2:value></w2:item><w2:item><w2:label>우수</w2:label><w2:value>2</w2:value></w2:item></w2:choices>';

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:100%;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getColumnNodeSet 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="90" inputType="text" id="h0" value="name(text)"></w2:column>';
    strTarget += '<w2:column width="100" inputType="text" id="h1" value="memo(숨김)"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="h2" value="grade(select)"></w2:column>';
    strTarget += '<w2:column width="150" inputType="text" id="h3" value="region(checkcombobox)"></w2:column>';
    strTarget += '<w2:column width="130" inputType="text" id="h4" value="city(autoComplete)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="h5" value="type(정적select)"></w2:column>';
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="brow1">';
    //  (중요) body 컬럼 id 는 dataList 컬럼 id 와 동일해야 셀에 데이터가 바인딩됨
    // name (text) -> 미지원 inputType -> undefined
    strTarget += '<w2:column width="90" inputType="text" id="name" dataList="name"></w2:column>';
    // memo (text) -> setColumnVisible(1,false) 로 숨김
    strTarget += '<w2:column width="100" inputType="text" id="memo" dataList="memo"></w2:column>';
    // grade (select, dlt_grade nodeset itemset) -> 채워진 객체
    strTarget += '<w2:column width="120" inputType="select" id="grade" dataList="grade">' + itemset + '</w2:column>';
    // region (checkcombobox, dlt_grade nodeset itemset) -> 채워진 객체
    strTarget += '<w2:column width="150" inputType="checkcombobox" id="region" dataList="region">' + itemset + '</w2:column>';
    // city (autoComplete, dlt_grade nodeset itemset) -> 채워진 객체
    strTarget += '<w2:column width="130" inputType="autoComplete" id="city" dataList="city">' + itemset + '</w2:column>';
    // type (select, 정적 인라인 item -> DataList nodeset 아님) -> 빈 문자열 객체
    strTarget += '<w2:column width="*" inputType="select" id="type" dataList="type">' + staticItemset + '</w2:column>';
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 두번째 Column(memo) 숨김 -> ID 조회는 숨김과 무관하게 동작
    target1.setColumnVisible(1, false);
}



// getColumnNodeSet 조회 (메인 검증 - ID)
//  - columnInfo 파라미터에 Body Column 의 ID 를 전달하여 조회
scwin.btn_getColumnNodeSet_onclick = function () {
    let columnInfo = par_columnInfo.getValue();

    let colIndex = target1.getColumnIndex(columnInfo);
    let info = target1.getColumnNodeSet(columnInfo);

    let result;
    if (typeof info === 'undefined') {
        result = "undefined";
    } else if (info === null) {
        result = "null";
    } else {
        result = "{ nodeset='" + info.nodeset + "', value='" + info.value + "', label='" + info.label + "' }";
    }

    wf_body_bottom.getObj("scwin").setReturnValue("getColumnNodeSet('" + columnInfo + "') [getColumnIndex:" + colIndex + "] -> " + result);
}
